import React, { Suspense, lazy } from "react";
import ReactDOM from "react-dom/client";
import App from "./App";
import "./theme/tokens.css";
import "./styles.css";

// UI-009 (issue #31): the preproduction prototype pack lives behind hash
// routes (#/prototype/*) as a lazy chunk — it never loads in the normal shell.
const PrototypeApp = lazy(() => import("./prototype/PrototypeApp"));

ReactDOM.createRoot(document.getElementById("root")!).render(
  <React.StrictMode>
    {window.location.hash.startsWith("#/prototype") ? (
      <Suspense fallback={null}>
        <PrototypeApp />
      </Suspense>
    ) : (
      <App />
    )}
  </React.StrictMode>,
);

import type { ReactNode } from "react";
import {
  Button,
  Toolbar,
  ToolbarButton,
  Tooltip,
} from "@fluentui/react-components";
import {
  ArrowExportUp24Regular,
  ArrowRepeatAll24Regular,
  CheckmarkCircle24Regular,
  ChevronLeft24Regular,
  Dismiss24Regular,
  DocumentBulletList24Regular,
  FolderOpen24Regular,
  MoreHorizontal24Regular,
  Next24Regular,
  Pause24Regular,
  Play24Regular,
  Previous24Regular,
  Settings24Regular,
  SlideTextSparkle24Regular,
  Stop24Regular,
} from "@fluentui/react-icons";
import { ja } from "../strings/ja";
import { PitchSegmented } from "../components/PitchSegmented";
import { TitleBar } from "../components/TitleBar";
import { StatusBar } from "../components/StatusBar";
import type { PitchView, MockNote } from "./mockData";
import {
  DURATION_SEC,
  LOOP_RANGE,
  formatTime,
  noteName,
  spellingLabel,
  writtenMidi,
} from "./mockData";
import type { MockPlayer } from "./useMockPlayer";

/**
 * Prototype chrome — mirrors the real shell components' layout (same
 * hs-* classes) while exposing the state the UI-009 scenarios need.
 * Production strings come from ja.*; prototype-only labels from
 * ja.prototype.*.
 */

/* --------------------------- command bar --------------------------- */

export interface ProtoShellState {
  hasAudio: boolean;
  hasScore: boolean;
  reviewCount: number;
  transcribing?: boolean;
}

export type ProtoCommand =
  | "open"
  | "transcribe"
  | "review"
  | "export"
  | "settings"
  | "overflow";

export function ProtoCommandBar({
  state,
  pitch,
  onPitch,
  onCommand,
  longLabels = false,
}: {
  state: ProtoShellState;
  pitch: PitchView;
  onPitch(v: PitchView): void;
  onCommand(id: ProtoCommand): void;
  /** P2 density: use the longest plausible command labels. */
  longLabels?: boolean;
}) {
  const openLabel = longLabels ? ja.commandBar.open : "開く";
  const transcribeLabel = state.hasScore ? "採譜し直す" : "採譜";
  const reviewLabel = state.reviewCount > 0 ? `要確認（${state.reviewCount}）` : "要確認";
  return (
    <Toolbar className="hs-commandbar" aria-label={ja.commandBar.regionLabel}>
      <Tooltip content={`${ja.commandBar.open}（Ctrl+O）`} relationship="label">
        <ToolbarButton icon={<FolderOpen24Regular />} onClick={() => onCommand("open")}>
          {openLabel}
        </ToolbarButton>
      </Tooltip>
      <Tooltip content="採譜を開始する" relationship="label">
        <ToolbarButton
          icon={<Play24Regular />}
          appearance="primary"
          disabled={!state.hasAudio || state.transcribing}
          onClick={() => onCommand("transcribe")}
        >
          {transcribeLabel}
        </ToolbarButton>
      </Tooltip>

      <span className="hs-commandbar__spacer" />
      <PitchSegmented value={pitch} onChange={onPitch} />
      <span className="hs-commandbar__spacer" />

      <Tooltip content={ja.commandBar.review} relationship="label">
        <ToolbarButton
          icon={<CheckmarkCircle24Regular />}
          disabled={!state.hasScore || state.reviewCount === 0}
          onClick={() => onCommand("review")}
        >
          {reviewLabel}
        </ToolbarButton>
      </Tooltip>
      <Tooltip content="MusicXML・PDF・MIDIを書き出す" relationship="label">
        <ToolbarButton
          icon={<ArrowExportUp24Regular />}
          disabled={!state.hasScore}
          onClick={() => onCommand("export")}
        >
          {ja.commandBar.export}
        </ToolbarButton>
      </Tooltip>
      <Tooltip content={ja.commandBar.settings} relationship="label">
        <ToolbarButton
          icon={<Settings24Regular />}
          aria-label={ja.commandBar.settings}
          onClick={() => onCommand("settings")}
        />
      </Tooltip>
      <Tooltip content={ja.commandBar.overflow} relationship="label">
        <Button appearance="subtle" icon={<MoreHorizontal24Regular />} disabled />
      </Tooltip>
    </Toolbar>
  );
}

/* ----------------------------- waveform ----------------------------- */

export function ProtoWaveform({
  positionSec,
  loop,
  loopRange,
  loaded,
  onSeek,
}: {
  positionSec: number;
  loop: boolean;
  loopRange: { startSec: number; endSec: number } | null;
  loaded: boolean;
  onSeek?(sec: number): void;
}) {
  const bars: number[] = [];
  if (loaded) {
    // deterministic pseudo-waveform
    for (let i = 0; i < 120; i++) {
      const v = Math.abs(Math.sin(i * 0.55) * Math.cos(i * 0.13));
      bars.push(0.15 + v * 0.85);
    }
  }
  const width = 720;
  const height = 72;
  const playX = (positionSec / DURATION_SEC) * width;
  return (
    <div
      className="hs-waveform hs-proto-waveform"
      role="region"
      aria-label={ja.waveform.regionLabel}
      tabIndex={0}
    >
      {loaded ? (
        <svg
          width="100%"
          height="100%"
          viewBox={`0 0 ${width} ${height}`}
          preserveAspectRatio="none"
          onClick={(e) => {
            if (!onSeek) return;
            const rect = e.currentTarget.getBoundingClientRect();
            onSeek(((e.clientX - rect.left) / rect.width) * DURATION_SEC);
          }}
        >
          {loop && loopRange && (
            <rect
              x={(loopRange.startSec / DURATION_SEC) * width}
              y={0}
              width={((loopRange.endSec - loopRange.startSec) / DURATION_SEC) * width}
              height={height}
              fill="var(--hs-waveform-selection)"
              aria-hidden="true"
            />
          )}
          {bars.map((h, i) => {
            const x = (i / bars.length) * width;
            const bh = h * (height - 10);
            return (
              <rect
                key={i}
                x={x + 1.5}
                y={(height - bh) / 2}
                width={width / bars.length - 3}
                height={bh}
                rx={1}
                fill={x <= playX ? "var(--hs-waveform-played)" : "var(--hs-waveform)"}
              />
            );
          })}
          <line
            x1={playX}
            x2={playX}
            y1={0}
            y2={height}
            stroke="var(--hs-playhead)"
            strokeWidth={2}
          />
        </svg>
      ) : (
        ja.waveform.placeholder
      )}
    </div>
  );
}

/* ----------------------------- transport ----------------------------- */

export function ProtoTransport({
  player,
  enabled,
}: {
  player: MockPlayer;
  enabled: boolean;
}) {
  const t = ja.prototype.transport;
  const followActive = player.follow === "on";
  return (
    <Toolbar className="hs-transport" aria-label={ja.transport.regionLabel}>
      <Tooltip content={`${t.skipBack}（J）`} relationship="label">
        <ToolbarButton
          icon={<Previous24Regular />}
          aria-label={t.skipBack}
          disabled={!enabled}
          onClick={() => player.seekBy(-5)}
        />
      </Tooltip>
      <Tooltip content={`${t.playPause}（Space）`} relationship="label">
        <ToolbarButton
          icon={player.playing ? <Pause24Regular /> : <Play24Regular />}
          aria-label={player.playing ? t.pause : t.play}
          disabled={!enabled}
          appearance="primary"
          onClick={player.togglePlay}
        />
      </Tooltip>
      <Tooltip content={`${t.stop}（Shift+Space）`} relationship="label">
        <ToolbarButton
          icon={<Stop24Regular />}
          aria-label={t.stop}
          disabled={!enabled}
          onClick={player.stop}
        />
      </Tooltip>
      <Tooltip content={`${t.skipForward}（L）`} relationship="label">
        <ToolbarButton
          icon={<Next24Regular />}
          aria-label={t.skipForward}
          disabled={!enabled}
          onClick={() => player.seekBy(5)}
        />
      </Tooltip>
      <span className="hs-transport__time" aria-label={t.position}>
        {formatTime(player.positionSec)} / {formatTime(DURATION_SEC)}
      </span>

      <span className="hs-transport__spacer" />

      <Tooltip content={`${t.rate} ${player.rate.toFixed(2).replace(/\.?0+$/, "")}×`} relationship="label">
        <ToolbarButton disabled={!enabled} onClick={player.cycleRate}>
          {player.rate.toFixed(2).replace(/\.?0+$/, "")}×
        </ToolbarButton>
      </Tooltip>
      <Tooltip content={`${t.loopToggle}（Ctrl+L）`} relationship="label">
        <ToolbarButton
          icon={<ArrowRepeatAll24Regular />}
          aria-label={t.loop}
          aria-pressed={player.loop}
          disabled={!enabled}
          onClick={player.toggleLoop}
          className={player.loop ? "hs-proto-toggle--on" : undefined}
        />
      </Tooltip>
      <Tooltip content={t.followFull} relationship="label">
        <ToolbarButton
          icon={<SlideTextSparkle24Regular />}
          aria-label={t.followFull}
          aria-pressed={followActive}
          disabled={!enabled}
          onClick={() => player.setFollowOn(!followActive)}
          className={followActive ? "hs-proto-toggle--on" : undefined}
        >
          {t.follow}
        </ToolbarButton>
      </Tooltip>
    </Toolbar>
  );
}

/* ---------------------------- properties ---------------------------- */

export type NoteEditAction =
  | "pitchUp"
  | "pitchDown"
  | "enharmonic"
  | "delete"
  | "restore"
  | "playSource";

export function ProtoProperties({
  note,
  pitch,
  open,
  onClose,
  onReopen,
  onAction,
}: {
  note: MockNote | null;
  pitch: PitchView;
  open: boolean;
  onClose(): void;
  onReopen(): void;
  onAction?(a: NoteEditAction): void;
}) {
  const p = ja.prototype.properties;
  if (!open) {
    // Collapsed state: slim strip keeps the panel recoverable and proves
    // task completion does not depend on the panel being open (§21).
    return (
      <aside className="hs-proto-props-collapsed" aria-label={p.title}>
        <button type="button" className="hs-proto-props-reopen" onClick={onReopen}>
          <ChevronLeft24Regular aria-hidden="true" />
          <span>{p.reopen}</span>
        </button>
      </aside>
    );
  }
  const displayMidi = note ? writtenMidi(note.midiConcert, pitch) : null;
  return (
    <aside className="hs-properties" aria-label={ja.properties.regionLabel}>
      <div className="hs-proto-props__header">
        <h2 className="hs-properties__title">{p.title}</h2>
        <Tooltip content={p.close} relationship="label">
          <Button
            appearance="subtle"
            size="small"
            icon={<Dismiss24Regular />}
            aria-label={p.close}
            onClick={onClose}
          />
        </Tooltip>
      </div>
      {note && displayMidi != null ? (
        <>
          <h3 className="hs-proto-props__section">{p.noteSection}</h3>
          <dl className="hs-proto-props__fields">
            <div>
              <dt>{p.fields.pitch}</dt>
              <dd>
                {noteName(displayMidi)}
                {pitch === "hornF" && (
                  <span className="hs-proto-props__dim">（{p.writtenNoteSuffix}）</span>
                )}
              </dd>
            </div>
            <div>
              <dt>{p.fields.spelling}</dt>
              <dd>{spellingLabel(displayMidi)}</dd>
            </div>
            <div>
              <dt>{p.fields.measure}</dt>
              <dd>第{note.measure}小節</dd>
            </div>
            <div>
              <dt>{p.fields.onset}</dt>
              <dd>{note.beat}拍目</dd>
            </div>
            <div>
              <dt>{p.fields.duration}</dt>
              <dd>{note.durationLabel}</dd>
            </div>
            <div>
              <dt>{p.fields.confidence}</dt>
              <dd>{note.confidence}%</dd>
            </div>
            <div>
              <dt>{p.fields.sourcePosition}</dt>
              <dd>{formatTime(note.onsetSec)}</dd>
            </div>
          </dl>
          {note.deleted && <p className="hs-proto-props__dim">{p.deleted}</p>}
          <div className="hs-proto-props__actions">
            <Button size="small" onClick={() => onAction?.("pitchUp")}>
              {p.actions.pitchUp}
            </Button>
            <Button size="small" onClick={() => onAction?.("pitchDown")}>
              {p.actions.pitchDown}
            </Button>
            <Button size="small" onClick={() => onAction?.("enharmonic")}>
              {p.actions.enharmonic}
            </Button>
            {note.deleted ? (
              <Button size="small" onClick={() => onAction?.("restore")}>
                {p.actions.restore}
              </Button>
            ) : (
              <Button size="small" onClick={() => onAction?.("delete")}>
                {p.actions.delete}
              </Button>
            )}
            <Button size="small" onClick={() => onAction?.("playSource")}>
              {p.actions.playSource}
            </Button>
          </div>
        </>
      ) : (
        <p className="hs-properties__body">{p.empty}</p>
      )}
    </aside>
  );
}

/* --------------------------- review banner --------------------------- */

export function ReviewBanner({
  count,
  onOpen,
}: {
  count: number;
  onOpen(): void;
}) {
  return (
    <div className="hs-proto-reviewbanner" role="note">
      <DocumentBulletList24Regular aria-hidden="true" />
      <span>{ja.prototype.reviewBanner.text(count)}</span>
      <Button appearance="primary" size="small" onClick={onOpen}>
        {ja.prototype.reviewBanner.cta}
      </Button>
    </div>
  );
}

/* ------------------------------ shell ------------------------------ */

export function ProtoShell({
  documentTitle,
  state,
  pitch,
  onPitch,
  onCommand,
  longLabels,
  player,
  transportEnabled,
  properties,
  banner,
  status,
  children,
}: {
  documentTitle?: string;
  state: ProtoShellState;
  pitch: PitchView;
  onPitch(v: PitchView): void;
  onCommand(id: ProtoCommand): void;
  longLabels?: boolean;
  player: MockPlayer;
  transportEnabled: boolean;
  properties?: ReactNode;
  banner?: ReactNode;
  status: string;
  children: ReactNode;
}) {
  return (
    <div className="hs-shell">
      <TitleBar documentTitle={documentTitle} />
      <ProtoCommandBar
        state={state}
        pitch={pitch}
        onPitch={onPitch}
        onCommand={onCommand}
        longLabels={longLabels}
      />
      <ProtoWaveform
        positionSec={player.positionSec}
        loop={player.loop}
        loopRange={LOOP_RANGE}
        loaded={state.hasAudio}
        onSeek={state.hasAudio ? (s) => player.seekTo(s) : undefined}
      />
      <div className="hs-main">
        <div className="hs-proto-scorecol">
          {banner}
          {children}
        </div>
        {properties}
      </div>
      <ProtoTransport player={player} enabled={transportEnabled} />
      <StatusBar message={status} />
    </div>
  );
}

import { forwardRef } from "react";
import { ja } from "../strings/ja";
import {
  diatonicStep,
  hasAccidental,
  measureAtTime,
  noteName,
  writtenMidi,
  type MockIssue,
  type MockNote,
  type PitchView,
} from "./mockData";

/**
 * Mock score — continuous view (連続表示, GUI_UX_SPEC §10 default candidate).
 * Notes are real SVG glyphs laid out on a staff so density/hierarchy reads
 * like a score; engraving correctness is a non-goal (issue non-goals).
 *
 * Selection / playback highlight / review markers are all driven by props so
 * the same surface serves the shell, score, review and export states.
 */

const MEASURES_PER_SYSTEM = 4;
const MEASURE_W = 168;
const LEFT_PAD = 56;
const SYSTEM_H = 148;
const STAFF_TOP = 52; // y of the top staff line inside a system block
const LINE_GAP = 8; // distance between staff lines
const BOTTOM_STEP = diatonicStep(64); // E4 = bottom line (treble staff)

function stepToY(midi: number): number {
  return STAFF_TOP + 4 * LINE_GAP - (diatonicStep(midi) - BOTTOM_STEP) * (LINE_GAP / 2);
}

function noteX(note: MockNote): number {
  const m = (note.measure - 1) % MEASURES_PER_SYSTEM;
  return LEFT_PAD + m * MEASURE_W + (note.beat - 1) * 40 + 14;
}

function systemIndex(measure: number): number {
  return Math.floor((measure - 1) / MEASURES_PER_SYSTEM);
}

function systemTop(measure: number): number {
  return systemIndex(measure) * SYSTEM_H;
}

function NoteGlyph({ midi, beats }: { midi: number; beats: number }) {
  const y = stepToY(midi);
  const hollow = beats >= 2;
  const stemUp = diatonicStep(midi) < diatonicStep(71); // below B4 → stem up
  const stemLen = 30;
  const ink = "var(--hs-proto-ink)";
  const ledgers: number[] = [];
  // Ledger lines for notes outside the 5-line staff.
  for (let s = 1; STAFF_TOP + 4 * LINE_GAP + s * LINE_GAP <= y; s++) {
    ledgers.push(STAFF_TOP + 4 * LINE_GAP + s * LINE_GAP);
  }
  for (let s = 1; STAFF_TOP - s * LINE_GAP >= y; s++) {
    ledgers.push(STAFF_TOP - s * LINE_GAP);
  }
  return (
    <>
      {ledgers.map((ly) => (
        <line key={ly} x1={-11} x2={11} y1={ly - y} y2={ly - y} stroke={ink} strokeWidth={1} />
      ))}
      {hasAccidental(midi) && (
        <text x={-16} y={4} fontSize={13} fill={ink} textAnchor="middle">
          ♯
        </text>
      )}
      <ellipse
        cx={0}
        cy={0}
        rx={5.4}
        ry={3.8}
        transform="rotate(-18)"
        fill={hollow ? "var(--hs-surface-score)" : ink}
        stroke={ink}
        strokeWidth={1.4}
        className="hs-proto-note__head"
      />
      {beats < 4 && (
        <line
          x1={stemUp ? 5 : -5}
          x2={stemUp ? 5 : -5}
          y1={0}
          y2={stemUp ? -stemLen : stemLen}
          stroke={ink}
          strokeWidth={1.3}
          className="hs-proto-note__stem"
        />
      )}
    </>
  );
}

export interface ProtoScoreProps {
  notes: MockNote[];
  pitch: PitchView;
  selectedId: string | null;
  onSelect(id: string | null): void;
  /** Playback position in seconds; null = no highlight. */
  positionSec: number | null;
  /** Issue markers (dotted underline + glyph) rendered on pending issues. */
  issues?: MockIssue[];
  focusedIssueId?: string | null;
  onBackgroundClick?(): void;
  /** Manual scroll inside the score surface (drives follow suspension). */
  onScroll?(): void;
}

export const ProtoScore = forwardRef<HTMLDivElement, ProtoScoreProps>(
  function ProtoScore(
    { notes, pitch, selectedId, onSelect, positionSec, issues, focusedIssueId, onBackgroundClick, onScroll },
    ref,
  ) {
    const systems = Math.ceil(12 / MEASURES_PER_SYSTEM);
    const width = LEFT_PAD + MEASURES_PER_SYSTEM * MEASURE_W + 20;
    const height = systems * SYSTEM_H + 24;
    const activeMeasure = positionSec != null ? measureAtTime(positionSec) : null;
    const issueByNote = new Map((issues ?? []).map((i) => [i.noteId, i]));

    return (
      <div
        ref={ref}
        className="hs-proto-score"
        role="region"
        aria-label={ja.prototype.scoreView.regionLabel}
        tabIndex={0}
        onClick={onBackgroundClick}
        onScroll={onScroll}
      >
        <svg
          width={width}
          height={height}
          className="hs-proto-score__svg"
          role="presentation"
        >
          {pitch === "hornF" && (
            <text x={8} y={20} fontSize={12} className="hs-proto-score__caption">
              F管ホルン（{ja.prototype.scoreView.hornCaption}）
            </text>
          )}
          {Array.from({ length: systems }, (_, sys) => {
            const top = sys * SYSTEM_H;
            const firstMeasure = sys * MEASURES_PER_SYSTEM + 1;
            const lastMeasure = Math.min(firstMeasure + MEASURES_PER_SYSTEM - 1, 12);
            return (
              <g key={sys} transform={`translate(0,${top})`}>
                {/* staff lines */}
                {[0, 1, 2, 3, 4].map((l) => (
                  <line
                    key={l}
                    x1={LEFT_PAD - 8}
                    x2={LEFT_PAD + MEASURES_PER_SYSTEM * MEASURE_W}
                    y1={STAFF_TOP + l * LINE_GAP}
                    y2={STAFF_TOP + l * LINE_GAP}
                    stroke="var(--hs-proto-ink)"
                    strokeWidth={1}
                  />
                ))}
                {/* barlines + measure numbers */}
                {Array.from({ length: lastMeasure - firstMeasure + 2 }, (_, i) => {
                  const m = firstMeasure + i;
                  const x = LEFT_PAD + i * MEASURE_W;
                  const isEnd = i === lastMeasure - firstMeasure + 1;
                  return (
                    <g key={i}>
                      <line
                        x1={x}
                        x2={x}
                        y1={STAFF_TOP}
                        y2={STAFF_TOP + 4 * LINE_GAP}
                        stroke="var(--hs-proto-ink)"
                        strokeWidth={isEnd ? 3 : 1}
                      />
                      {m <= 12 && (
                        <text
                          x={x + 3}
                          y={STAFF_TOP - 8}
                          fontSize={10}
                          className="hs-proto-score__measureNo"
                        >
                          {m}
                        </text>
                      )}
                    </g>
                  );
                })}
                {/* playback measure wash (subtle, §10) */}
                {activeMeasure != null &&
                  activeMeasure >= firstMeasure &&
                  activeMeasure <= lastMeasure && (
                    <rect
                      x={LEFT_PAD + (activeMeasure - firstMeasure) * MEASURE_W}
                      y={STAFF_TOP - 16}
                      width={MEASURE_W}
                      height={4 * LINE_GAP + 32}
                      fill="var(--hs-score-current-measure)"
                    />
                  )}
              </g>
            );
          })}

          {notes.map((note) => {
            if (note.deleted) return null;
            const x = noteX(note);
            const displayMidi = writtenMidi(note.midiConcert, pitch);
            const y = systemTop(note.measure) + stepToY(displayMidi);
            const selected = note.id === selectedId;
            const issue = issueByNote.get(note.id);
            const isFocusedIssue = issue && issue.id === focusedIssueId;
            return (
              <g
                key={note.id}
                transform={`translate(${x},${y})`}
                role="button"
                aria-label={`第${note.measure}小節 ${note.beat}拍 ${noteName(displayMidi)}`}
                aria-pressed={selected}
                tabIndex={-1}
                className="hs-proto-note"
                onClick={(e) => {
                  e.stopPropagation();
                  onSelect(note.id);
                }}
              >
                {selected && (
                  <rect
                    x={-14}
                    y={-16}
                    width={30}
                    height={note.durationBeats < 4 ? 48 : 34}
                    rx={4}
                    fill="var(--hs-score-selection)"
                    stroke="var(--hs-accent)"
                    strokeWidth={1}
                  />
                )}
                <NoteGlyph midi={displayMidi} beats={note.durationBeats} />
                {issue && (
                  <g
                    aria-hidden="true"
                    className={isFocusedIssue ? "hs-proto-issue hs-proto-issue--focus" : "hs-proto-issue"}
                  >
                    <line
                      x1={-10}
                      x2={12}
                      y1={14}
                      y2={14}
                      stroke="var(--hs-review-marker)"
                      strokeWidth={2}
                      strokeDasharray="3 3"
                    />
                    <circle cx={0} cy={-26} r={6} fill="var(--hs-review-marker)" />
                    <text x={0} y={-22.5} fontSize={9} textAnchor="middle" fill="var(--hs-surface-score)">
                      ?
                    </text>
                  </g>
                )}
                {/* enlarge hit area */}
                <rect x={-14} y={-34} width={30} height={60} fill="transparent" />
              </g>
            );
          })}
        </svg>
      </div>
    );
  },
);

export const SCORE_METRICS = {
  MEASURES_PER_SYSTEM,
  MEASURE_W,
  LEFT_PAD,
  SYSTEM_H,
  STAFF_TOP,
  systemTop,
  systemIndex,
};

import { useEffect, useState } from "react";
import { FluentProvider } from "@fluentui/react-components";
import { ja } from "../strings/ja";
import { hsLightTheme, hsDarkTheme, type ThemeMode } from "../theme/fluentTheme";
import { useThemeMode } from "../theme/useThemeMode";
import { IndexPage } from "./pages/IndexPage";
import { ShellPage } from "./pages/ShellPage";
import { DensityPage } from "./pages/DensityPage";
import { ScorePage } from "./pages/ScorePage";
import { ReviewPage } from "./pages/ReviewPage";
import { ExportPage } from "./pages/ExportPage";
import "./prototype.css";

/**
 * UI-009 preproduction prototype pack (issue #31).
 * Mounted only under hash routes `#/prototype/*` (lazy chunk from main.tsx).
 * All state is deterministic mock data — no engine, no audio, no persistence.
 */

type Route = "index" | "shell" | "density" | "score" | "review" | "export";

const ROUTES: Route[] = ["shell", "density", "score", "review", "export"];

/** `#/prototype/<route>/<param...>` → deep-linkable mock states. */
function parseHash(): { route: Route; params: string[] } {
  const h = window.location.hash.replace(/^#\/?prototype\/?/, "");
  const [head, ...rest] = h.split("/").filter(Boolean);
  const route = (ROUTES as string[]).includes(head) ? (head as Route) : "index";
  return { route, params: rest };
}

function useHashRoute(): { route: Route; params: string[] } {
  const [state, setState] = useState(parseHash);
  useEffect(() => {
    const onHash = () => setState(parseHash());
    window.addEventListener("hashchange", onHash);
    return () => window.removeEventListener("hashchange", onHash);
  }, []);
  return state;
}

const PAGE_META: Record<Route, { hash: string; title: string }> = {
  index: { hash: "#/prototype", title: ja.prototype.nav.index },
  shell: { hash: "#/prototype/shell", title: ja.prototype.pages.shell.title },
  density: { hash: "#/prototype/density", title: ja.prototype.pages.density.title },
  score: { hash: "#/prototype/score", title: ja.prototype.pages.score.title },
  review: { hash: "#/prototype/review", title: ja.prototype.pages.review.title },
  export: { hash: "#/prototype/export", title: ja.prototype.pages.export.title },
};

export default function PrototypeApp() {
  const { mode, resolved, select } = useThemeMode();
  const { route, params } = useHashRoute();
  const theme = resolved === "dark" ? hsDarkTheme : hsLightTheme;
  const nav = ja.prototype.nav;

  const exitPrototype = () => {
    window.location.hash = "";
    window.location.reload();
  };

  return (
    <FluentProvider theme={theme}>
      <div className="hs-proto-page">
        <nav className="hs-proto-nav" aria-label={nav.regionLabel}>
          <span className="hs-proto-nav__badge">{nav.badge}</span>
          {(Object.keys(PAGE_META) as Route[]).map((key) => (
            <a
              key={key}
              href={PAGE_META[key].hash}
              aria-current={route === key ? "page" : undefined}
            >
              {PAGE_META[key].title}
            </a>
          ))}
          <span className="hs-proto-nav__spacer" />
          <label>
            {nav.themeLabel}:{" "}
            <select
              value={mode}
              onChange={(e) => select(e.target.value as ThemeMode)}
              aria-label={nav.themeLabel}
            >
              <option value="system">{nav.themeSystem}</option>
              <option value="light">{nav.themeLight}</option>
              <option value="dark">{nav.themeDark}</option>
            </select>
          </label>
          <a
            href="#"
            onClick={(e) => {
              e.preventDefault();
              exitPrototype();
            }}
          >
            {nav.exit}
          </a>
        </nav>

        {route === "index" && <IndexPage />}
        {route === "shell" && <ShellPage key={params.join("/")} initial={params[0]} />}
        {route === "density" && (
          <DensityPage key={params.join("/")} view={params[0]} theme={params[1]} />
        )}
        {route === "score" && <ScorePage />}
        {route === "review" && <ReviewPage />}
        {route === "export" && (
          <ExportPage key={params.join("/")} initial={params[0]} phase={params[1]} />
        )}
      </div>
    </FluentProvider>
  );
}

/**
 * UI-009 prototype pack — deterministic mock data (issue #31).
 *
 * Everything here is fixed sample data: no audio decoding, no engine, no
 * randomness. The shapes mirror the future canonical model (note ids,
 * ReviewIssue reasons, concert-vs-written pitch) closely enough to validate
 * the information hierarchy in GUI_UX_SPEC.
 */

export type PitchView = "concert" | "hornF";

export interface MockNote {
  /** Canonical note id — selection survives the concert/F管ホルン switch. */
  id: string;
  /** 1-based measure number. */
  measure: number;
  /** 1-based beat position inside the measure. */
  beat: number;
  /** Concert-pitch MIDI number (what was played / what sounds). */
  midiConcert: number;
  durationBeats: number;
  durationLabel: string;
  onsetSec: number;
  confidence: number;
  deleted: boolean;
}

/** Mock score: 4/4, 100 BPM → 1 beat = 0.6 s, 1 measure = 2.4 s. */
export const BPM = 100;
export const BEAT_SEC = 60 / BPM;
export const MEASURE_SEC = BEAT_SEC * 4;
export const MEASURE_COUNT = 12;
export const DURATION_SEC = MEASURE_COUNT * MEASURE_SEC; // 28.8 s

/** Loop range used by the mocked transport (measures 5–8). */
export const LOOP_RANGE = { startSec: 4 * MEASURE_SEC, endSec: 8 * MEASURE_SEC };

const DURATION_LABEL: Record<number, string> = {
  4: "全音符",
  2: "二分音符",
  1: "四分音符",
  0.5: "八分音符",
};

/** Fixed melody, [concert midi, beats] per note, one array per measure. */
const MELODY: ReadonlyArray<ReadonlyArray<readonly [number, number]>> = [
  [[60, 1], [62, 1], [64, 1], [65, 1]],
  [[67, 2], [65, 1], [64, 1]],
  [[64, 1], [62, 1], [60, 2]],
  [[62, 1], [64, 1], [62, 1], [55, 1]],
  [[60, 2], [64, 2]],
  [[65, 1], [67, 1], [69, 2]],
  [[67, 1], [65, 1], [64, 1], [62, 1]],
  [[60, 4]],
  [[67, 1], [69, 1], [71, 1], [72, 1]],
  [[72, 2], [71, 1], [69, 1]],
  [[67, 1], [65, 1], [64, 1], [62, 1]],
  [[60, 4]],
];

/** Confidence is fixed per measure to give review markers variety. */
const CONFIDENCE = [88, 72, 91, 66, 95, 58, 84, 97, 76, 63, 81, 99];

export const NOTES: MockNote[] = (() => {
  let seq = 0;
  return MELODY.flatMap((measure, m) => {
    let beat = 1;
    return measure.map(([midi, beats]) => {
      const note: MockNote = {
        id: `n${String(seq++).padStart(3, "0")}`,
        measure: m + 1,
        beat,
        midiConcert: midi,
        durationBeats: beats,
        durationLabel: DURATION_LABEL[beats] ?? `${beats}拍`,
        onsetSec: m * MEASURE_SEC + (beat - 1) * BEAT_SEC,
        confidence: CONFIDENCE[m],
        deleted: false,
      };
      beat += beats;
      return note;
    });
  });
})();

/* ------------------------- pitch helpers ------------------------- */

const PC_SHARP = ["C", "C♯", "D", "D♯", "E", "F", "F♯", "G", "G♯", "A", "A♯", "B"];
const PC_FLAT = ["C", "D♭", "D", "E♭", "E", "F", "G♭", "G", "A♭", "A", "B♭", "B"];
/** pitch class → diatonic step inside the octave (sharp spelling). */
const DIATONIC_STEP = [0, 0, 1, 1, 2, 3, 3, 4, 4, 5, 5, 6];

export function noteName(midi: number): string {
  return `${PC_SHARP[midi % 12]}${Math.floor(midi / 12) - 1}`;
}

/** Enharmonic display for accidentals: 「F♯4（G♭4）」; naturals stay bare. */
export function spellingLabel(midi: number): string {
  const pc = midi % 12;
  const octave = Math.floor(midi / 12) - 1;
  const sharp = `${PC_SHARP[pc]}${octave}`;
  const flat = `${PC_FLAT[pc]}${octave}`;
  return sharp === flat ? sharp : `${sharp}（${flat}）`;
}

/** Horn in F: written pitch sounds a perfect fifth below → add 7 semitones. */
export function writtenMidi(midiConcert: number, view: PitchView): number {
  return view === "hornF" ? midiConcert + 7 : midiConcert;
}

/** Diatonic staff step (sharp spelling) for placing the notehead. */
export function diatonicStep(midi: number): number {
  return (Math.floor(midi / 12) - 1) * 7 + DIATONIC_STEP[midi % 12];
}

/** True when the sharp spelling carries an accidental sign. */
export function hasAccidental(midi: number): boolean {
  return PC_SHARP[midi % 12].includes("♯");
}

/* ------------------------- review issues ------------------------- */

export type IssueReason =
  | "quantizationAmbiguous"
  | "beatAlignmentUncertain"
  | "possibleTriplet"
  | "outsideHornRange"
  | "offsetAmbiguous";

export type IssueStatus = "pending" | "accepted" | "fixed" | "deleted";

export interface MockIssue {
  id: string;
  noteId: string;
  reason: IssueReason;
  confidence: number;
  status: IssueStatus;
}

function noteAt(measure: number, beat: number): MockNote {
  const n = NOTES.find((n) => n.measure === measure && n.beat === beat);
  if (!n) throw new Error(`mock: no note at m${measure} b${beat}`);
  return n;
}

/** Five deterministic ReviewIssues (P4) spread across the score. */
export function buildIssues(): MockIssue[] {
  const pick = (measure: number, beat: number, reason: IssueReason, confidence: number) => ({
    id: `ri-${measure}${String(beat).padStart(2, "0")}`,
    noteId: noteAt(measure, beat).id,
    reason,
    confidence,
    status: "pending" as IssueStatus,
  });
  return [
    pick(2, 1, "quantizationAmbiguous", 72),
    pick(4, 4, "outsideHornRange", 66),
    pick(6, 3, "possibleTriplet", 58),
    pick(9, 3, "beatAlignmentUncertain", 76),
    pick(11, 3, "offsetAmbiguous", 63),
  ];
}

/* ------------------------- misc helpers ------------------------- */

export function formatTime(sec: number): string {
  const m = Math.floor(sec / 60);
  const s = sec - m * 60;
  return `${String(m).padStart(2, "0")}:${s.toFixed(1).padStart(4, "0")}`;
}

export function noteAtTime(sec: number): MockNote | null {
  let hit: MockNote | null = null;
  for (const n of NOTES) {
    if (n.deleted) continue;
    if (n.onsetSec <= sec && sec < n.onsetSec + n.durationBeats * BEAT_SEC) {
      hit = n;
      break;
    }
  }
  return hit;
}

export function measureAtTime(sec: number): number {
  return Math.min(MEASURE_COUNT, Math.max(1, Math.floor(sec / MEASURE_SEC) + 1));
}

/** Deterministic pseudo-waveform heights (0..1), 120 bars. */
export const WAVE_BARS: number[] = Array.from({ length: 120 }, (_, i) => {
  const v = Math.abs(Math.sin(i * 0.55) * Math.cos(i * 0.13));
  return 0.15 + v * 0.85;
});

