import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Button, Tooltip } from "@fluentui/react-components";
import {
  ArrowLeft24Regular,
  ArrowRight24Regular,
  ArrowUndo24Regular,
  Delete24Regular,
  Play24Regular,
} from "@fluentui/react-icons";
import { ja } from "../../strings/ja";
import {
  NOTES,
  buildIssues,
  type IssueStatus,
  type MockIssue,
  type MockNote,
  type PitchView,
} from "../mockData";
import { useMockPlayer } from "../useMockPlayer";
import { useProtoKeys } from "../useProtoKeys";
import { ProtoScore, SCORE_METRICS } from "../ProtoScore";
import { ProtoShell, type ProtoCommand } from "../ProtoChrome";

interface Edit {
  issueId: string;
  prevStatus: IssueStatus;
  noteId: string;
  prevMidi: number;
}

/**
 * P4 — 要確認 flow, keyboard-only (issue #31 + UX_VALIDATION Task F).
 * Five deterministic issues; every action is a real button (Tab/Enter) AND
 * has a dedicated shortcut shown in tooltips:
 *   ← → 前へ/次へ, R 元音源を再生, O 問題なし, Alt+↑↓ 半音,
 *   Delete 削除, Ctrl+Z 元に戻す, Esc 終了.
 */
export function ReviewPage() {
  const [pitch, setPitch] = useState<PitchView>("concert");
  const [notes, setNotes] = useState<MockNote[]>(() => NOTES.map((n) => ({ ...n })));
  const [issues, setIssues] = useState<MockIssue[]>(() => buildIssues());
  const [cursor, setCursor] = useState(0);
  const [status, setStatus] = useState<string>(ja.status.ready);
  const [undoStack, setUndoStack] = useState<Edit[]>([]);
  const scoreRef = useRef<HTMLDivElement>(null);
  const player = useMockPlayer();
  const r = ja.prototype.review;
  const ps = ja.prototype.status;

  const issue = issues[cursor] ?? null;
  const issueNote = notes.find((n) => n.id === issue?.noteId) ?? null;
  const pendingCount = issues.filter((i) => i.status === "pending").length;
  const allDone = pendingCount === 0;
  const selectedId = issueNote?.id ?? null;

  /* Keep the focused issue's measure visible. */
  useEffect(() => {
    const el = scoreRef.current;
    if (!el || !issueNote) return;
    el.scrollTo({ top: SCORE_METRICS.systemTop(issueNote.measure) - 20 });
  }, [issueNote]);

  const goTo = useCallback(
    (delta: number) => {
      setCursor((c) => Math.min(issues.length - 1, Math.max(0, c + delta)));
    },
    [issues.length],
  );

  const mutateNote = useCallback((id: string, fn: (n: MockNote) => Partial<MockNote>) => {
    setNotes((list) => list.map((n) => (n.id === id ? { ...n, ...fn(n) } : n)));
  }, []);

  const markIssue = useCallback(
    (next: IssueStatus, midiDelta = 0) => {
      if (!issue || !issueNote) return;
      setUndoStack((s) => [
        ...s,
        {
          issueId: issue.id,
          prevStatus: issue.status,
          noteId: issueNote.id,
          prevMidi: issueNote.midiConcert,
        },
      ]);
      setIssues((list) =>
        list.map((i) => (i.id === issue.id ? { ...i, status: next } : i)),
      );
      if (midiDelta !== 0) {
        mutateNote(issueNote.id, (n) => ({ midiConcert: n.midiConcert + midiDelta }));
        setStatus(ps.pitchFixed);
      } else if (next === "accepted") {
        setStatus(ps.issueResolved);
      } else if (next === "deleted") {
        mutateNote(issueNote.id, () => ({ deleted: true }));
        setStatus(ps.noteDeleted);
      }
    },
    [issue, issueNote, mutateNote, ps],
  );

  const undo = useCallback(() => {
    setUndoStack((stack) => {
      const last = stack[stack.length - 1];
      if (!last) {
        setStatus(ps.nothingToUndo);
        return stack;
      }
      setIssues((list) =>
        list.map((i) => (i.id === last.issueId ? { ...i, status: last.prevStatus } : i)),
      );
      mutateNote(last.noteId, () => ({ midiConcert: last.prevMidi, deleted: last.prevStatus === "deleted" }));
      setStatus(ps.undone);
      return stack.slice(0, -1);
    });
  }, [mutateNote, ps]);

  const playSource = useCallback(() => {
    if (!issueNote) return;
    player.seekTo(issueNote.onsetSec);
    player.play();
    setStatus(r.playingSource);
  }, [issueNote, player, r.playingSource]);

  const exit = useCallback(() => {
    window.location.hash = "#/prototype/score";
  }, []);

  const onCommand = useCallback(
    (id: ProtoCommand) => {
      if (id === "export") window.location.hash = "#/prototype/export";
      else if (id === "review") return;
      else if (id === "open") window.location.hash = "#/prototype/shell";
      else setStatus("プロトタイプではこの操作は省略しています");
    },
    [],
  );

  useProtoKeys(
    useMemo(
      () => [
        { combo: "ArrowLeft", run: () => goTo(-1) },
        { combo: "ArrowRight", run: () => goTo(1) },
        { combo: "r", run: playSource },
        { combo: "o", run: () => markIssue("accepted") },
        { combo: "Alt+ArrowUp", run: () => markIssue("fixed", 1) },
        { combo: "Alt+ArrowDown", run: () => markIssue("fixed", -1) },
        { combo: "Delete", run: () => markIssue("deleted") },
        { combo: "Backspace", run: () => markIssue("deleted") },
        { combo: "Ctrl+z", run: undo },
        { combo: "Escape", run: exit },
        { combo: "Space", run: player.togglePlay },
        { combo: "Ctrl+1", run: () => setPitch("concert") },
        { combo: "Ctrl+2", run: () => setPitch("hornF") },
      ],
      [goTo, playSource, markIssue, undo, exit, player.togglePlay],
    ),
  );

  const reason = issue ? r.reasons[issue.reason] : null;
  const statusLabel = issue ? r.status[issue.status] : null;

  return (
    <ProtoShell
      documentTitle={ja.prototype.shell.docTitle}
      state={{ hasAudio: true, hasScore: true, reviewCount: pendingCount }}
      pitch={pitch}
      onPitch={setPitch}
      onCommand={onCommand}
      player={player}
      transportEnabled
      status={status}
      banner={
        <div className="hs-proto-reviewbar" role="region" aria-label={r.title}>
          <div className="hs-proto-reviewbar__row">
            <span className="hs-proto-reviewbar__position">
              {allDone ? r.allDone : r.position(cursor + 1, issues.length)}
            </span>
            {!allDone && (
              <span className="hs-proto-reviewbar__confidence">
                {r.remaining(pendingCount)}
              </span>
            )}
            <span style={{ flex: 1 }} />
            <Button size="small" onClick={exit}>
              {r.exit}
            </Button>
          </div>
          {!allDone && issue && reason && (
            <>
              <div className="hs-proto-reviewbar__row">
                <span className="hs-proto-reviewbar__reason">{reason.title}</span>
                <span className="hs-proto-reviewbar__detail">{reason.detail}</span>
                <span className="hs-proto-reviewbar__confidence">
                  {r.confidence(issue.confidence)}
                </span>
                <span className="hs-proto-reviewbar__status">{statusLabel}</span>
              </div>
              <div className="hs-proto-reviewbar__row">
                <Tooltip content={`${ja.prototype.common.prev}（←）`} relationship="label">
                  <Button
                    icon={<ArrowLeft24Regular />}
                    disabled={cursor === 0}
                    onClick={() => goTo(-1)}
                  >
                    {ja.prototype.common.prev}
                  </Button>
                </Tooltip>
                <Tooltip content={`${r.playSource}（R）`} relationship="label">
                  <Button icon={<Play24Regular />} onClick={playSource}>
                    {r.playSource}
                  </Button>
                </Tooltip>
                <Tooltip content={`${r.markOk}（O）`} relationship="label">
                  <Button appearance="primary" onClick={() => markIssue("accepted")}>
                    {r.markOk}
                  </Button>
                </Tooltip>
                <Tooltip content={`${r.fixPitch}（Alt+↑↓）`} relationship="label">
                  <Button onClick={() => markIssue("fixed", 1)}>
                    {ja.prototype.properties.actions.pitchUp}
                  </Button>
                </Tooltip>
                <Tooltip content={`${r.fixPitch}（Alt+↑↓）`} relationship="label">
                  <Button onClick={() => markIssue("fixed", -1)}>
                    {ja.prototype.properties.actions.pitchDown}
                  </Button>
                </Tooltip>
                <Tooltip content={`${r.deleteNote}（Delete）`} relationship="label">
                  <Button icon={<Delete24Regular />} onClick={() => markIssue("deleted")}>
                    {r.deleteNote}
                  </Button>
                </Tooltip>
                <Tooltip content={`${r.undo}（Ctrl+Z）`} relationship="label">
                  <Button
                    icon={<ArrowUndo24Regular />}
                    disabled={undoStack.length === 0}
                    onClick={undo}
                  >
                    {r.undo}
                  </Button>
                </Tooltip>
                <Tooltip content={`${ja.prototype.common.next}（→）`} relationship="label">
                  <Button
                    icon={<ArrowRight24Regular />}
                    iconPosition="after"
                    disabled={cursor >= issues.length - 1}
                    onClick={() => goTo(1)}
                  >
                    {ja.prototype.common.next}
                  </Button>
                </Tooltip>
              </div>
            </>
          )}
          <div className="hs-proto-reviewbar__row">
            <span className="hs-proto-reviewbar__hint">{r.hint}</span>
          </div>
        </div>
      }
    >
      <ProtoScore
        ref={scoreRef}
        notes={notes}
        pitch={pitch}
        selectedId={selectedId}
        onSelect={() => undefined /* review mode pins selection to the issue */}
        positionSec={player.playing ? player.positionSec : null}
        issues={issues.filter((i) => i.status === "pending")}
        focusedIssueId={issue?.id ?? null}
      />
    </ProtoShell>
  );
}

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { Button } from "@fluentui/react-components";
import { ja } from "../../strings/ja";
import {
  NOTES,
  buildIssues,
  measureAtTime,
  type MockNote,
  type PitchView,
} from "../mockData";
import { useMockPlayer } from "../useMockPlayer";
import { useProtoKeys } from "../useProtoKeys";
import { ProtoScore, SCORE_METRICS } from "../ProtoScore";
import {
  ProtoProperties,
  ProtoShell,
  ReviewBanner,
  type NoteEditAction,
  type ProtoCommand,
} from "../ProtoChrome";

interface Edit {
  noteId: string;
  prevMidi: number;
  prevDeleted: boolean;
}

/**
 * P3 — score interaction (GUI_UX_SPEC §6–§11):
 * note click → canonical id → properties; playback highlight; concert /
 * F管ホルン switch preserving selection, position and loop; follow
 * suspend on manual scroll + resume; all note edits undoable (Ctrl+Z).
 */
export function ScorePage() {
  const [pitch, setPitch] = useState<PitchView>("concert");
  const [notes, setNotes] = useState<MockNote[]>(() => NOTES.map((n) => ({ ...n })));
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [propsOpen, setPropsOpen] = useState(false);
  const [status, setStatus] = useState<string>(ja.prototype.status.stopped);
  const [, setUndoStack] = useState<Edit[]>([]);
  const scoreRef = useRef<HTMLDivElement>(null);
  const programmaticScroll = useRef(false);
  const player = useMockPlayer();
  const issues = useMemo(() => buildIssues(), []);

  const selected = notes.find((n) => n.id === selectedId) ?? null;
  const t = ja.prototype.transport;
  const ps = ja.prototype.status;

  /* ---- follow: scroll active measure into view (§11) ---- */
  const lastScrolledMeasure = useRef(0);
  useEffect(() => {
    if (!player.playing || player.follow !== "on") return;
    const el = scoreRef.current;
    if (!el) return;
    const measure = measureAtTime(player.positionSec);
    if (measure === lastScrolledMeasure.current) return;
    lastScrolledMeasure.current = measure;
    programmaticScroll.current = true;
    el.scrollTo({ top: SCORE_METRICS.systemTop(measure) - 20 });
    // Instant jump: the resulting scroll event lands within a tick; the
    // short guard window must not swallow genuine manual scrolls.
    const id = window.setTimeout(() => (programmaticScroll.current = false), 80);
    return () => window.clearTimeout(id);
  }, [player.playing, player.follow, player.positionSec]);

  const onScoreScroll = useCallback(() => {
    if (programmaticScroll.current) return;
    if (player.playing) player.suspendFollow();
  }, [player]);

  /* ------------------------- editing ------------------------- */

  const mutateNote = useCallback(
    (id: string, fn: (n: MockNote) => Partial<MockNote>) => {
      setNotes((list) =>
        list.map((n) => (n.id === id ? { ...n, ...fn(n) } : n)),
      );
    },
    [],
  );

  const pushUndo = useCallback((note: MockNote) => {
    setUndoStack((s) => [
      ...s,
      { noteId: note.id, prevMidi: note.midiConcert, prevDeleted: note.deleted },
    ]);
  }, []);

  const doPitchDelta = useCallback(
    (delta: number) => {
      if (!selected) return;
      pushUndo(selected);
      mutateNote(selected.id, (n) => ({ midiConcert: n.midiConcert + delta }));
      setStatus(delta > 0 ? ps.pitchFixed : ps.pitchFixed);
    },
    [selected, pushUndo, mutateNote, ps],
  );

  const onAction = useCallback(
    (a: NoteEditAction) => {
      if (!selected) return;
      pushUndo(selected);
      switch (a) {
        case "pitchUp":
          mutateNote(selected.id, (n) => ({ midiConcert: n.midiConcert + 1 }));
          setStatus(ps.pitchFixed);
          break;
        case "pitchDown":
          mutateNote(selected.id, (n) => ({ midiConcert: n.midiConcert - 1 }));
          setStatus(ps.pitchFixed);
          break;
        case "enharmonic":
          // spelling-only change: pitch identical → nothing to mutate in mock;
          // recorded on the undo stack to prove the command is undoable.
          setStatus("異名同音の表記を切り替えました");
          break;
        case "delete":
          mutateNote(selected.id, () => ({ deleted: true }));
          setStatus(ps.noteDeleted);
          break;
        case "restore":
          mutateNote(selected.id, () => ({ deleted: false }));
          setStatus(ps.noteRestored);
          break;
        case "playSource":
          player.seekTo(selected.onsetSec);
          player.play();
          setStatus(ps.simulatedSeek);
          break;
      }
    },
    [selected, pushUndo, mutateNote, ps, player],
  );

  const undo = useCallback(() => {
    setUndoStack((stack) => {
      const last = stack[stack.length - 1];
      if (!last) {
        setStatus(ps.nothingToUndo);
        return stack;
      }
      mutateNote(last.noteId, () => ({
        midiConcert: last.prevMidi,
        deleted: last.prevDeleted,
      }));
      setStatus(ps.undone);
      return stack.slice(0, -1);
    });
  }, [mutateNote, ps]);

  /* ------------------------- navigation ------------------------- */

  const stepNote = useCallback(
    (delta: number) => {
      const list = notes.filter((n) => !n.deleted);
      if (list.length === 0) return;
      const idx = selectedId ? list.findIndex((n) => n.id === selectedId) : -1;
      const next = list[Math.min(list.length - 1, Math.max(0, idx + delta))] ?? list[0];
      setSelectedId(next.id);
      setPropsOpen(true);
      const el = scoreRef.current;
      if (el) {
        programmaticScroll.current = true;
        el.scrollTo({ top: SCORE_METRICS.systemTop(next.measure) - 20 });
        window.setTimeout(() => (programmaticScroll.current = false), 250);
      }
    },
    [notes, selectedId],
  );

  const onCommand = useCallback(
    (id: ProtoCommand) => {
      switch (id) {
        case "open":
          window.location.hash = "#/prototype/shell";
          break;
        case "transcribe":
          setStatus("プロトタイプでは採譜し直しは実行しません");
          break;
        case "review":
          window.location.hash = "#/prototype/review";
          break;
        case "export":
          window.location.hash = "#/prototype/export";
          break;
        case "settings":
          setStatus("設定画面はこのプロトタイプでは省略しています");
          break;
      }
    },
    [],
  );

  useProtoKeys(
    useMemo(
      () => [
        { combo: "Space", run: player.togglePlay },
        { combo: "Shift+Space", run: player.stop },
        { combo: "j", run: () => player.seekBy(-5) },
        { combo: "l", run: () => player.seekBy(5) },
        { combo: "Home", run: () => player.seekTo(0) },
        { combo: "End", run: () => player.seekTo(1e9) },
        { combo: "Ctrl+l", run: player.toggleLoop },
        { combo: "Ctrl+1", run: () => setPitch("concert") },
        { combo: "Ctrl+2", run: () => setPitch("hornF") },
        { combo: "Ctrl+z", run: undo },
        { combo: "Escape", run: () => setSelectedId(null) },
        { combo: "ArrowLeft", run: () => stepNote(-1) },
        { combo: "ArrowRight", run: () => stepNote(1) },
        { combo: "Alt+ArrowUp", run: () => doPitchDelta(1), enabled: () => !!selected },
        { combo: "Alt+ArrowDown", run: () => doPitchDelta(-1), enabled: () => !!selected },
        { combo: "Delete", run: () => onAction("delete"), enabled: () => !!selected && !selected.deleted },
      ],
      [player, undo, stepNote, doPitchDelta, onAction, selected],
    ),
  );

  return (
    <ProtoShell
      documentTitle={ja.prototype.shell.docTitle}
      state={{ hasAudio: true, hasScore: true, reviewCount: issues.length }}
      pitch={pitch}
      onPitch={setPitch}
      onCommand={onCommand}
      player={player}
      transportEnabled
      status={status}
      banner={
        player.follow === "paused" ? (
          <div className="hs-proto-follownote" role="status">
            <span>{t.followPaused}</span>
            <Button
              size="small"
              appearance="primary"
              onClick={() => {
                lastScrolledMeasure.current = -1; // force re-scroll to playhead
                player.resumeFollow();
              }}
            >
              {t.resumeFollow}
            </Button>
          </div>
        ) : (
          <ReviewBanner
            count={issues.filter((i) => i.status === "pending").length}
            onOpen={() => onCommand("review")}
          />
        )
      }
      properties={
        <ProtoProperties
          note={selected}
          pitch={pitch}
          open={propsOpen}
          onClose={() => setPropsOpen(false)}
          onReopen={() => setPropsOpen(true)}
          onAction={onAction}
        />
      }
    >
      <div style={{ position: "relative", flex: "1 1 auto", minHeight: 0, display: "flex", flexDirection: "column" }}>
        <ProtoScore
          ref={scoreRef}
          notes={notes}
          pitch={pitch}
          selectedId={selectedId}
          onSelect={(id) => {
            setSelectedId(id);
            setPropsOpen(true);
          }}
          positionSec={player.positionSec}
          issues={issues.filter((i) => i.status === "pending")}
          onBackgroundClick={() => setSelectedId(null)}
          onScroll={onScoreScroll}
        />
        <div
          className="hs-proto-dev"
          style={{ margin: 0, borderWidth: "1px 0 0", borderRadius: 0 }}
        >
          <span className="hs-proto-dev__label">{ja.prototype.dev.controlsLabel}</span>
          <span>{ja.prototype.scoreView.hint}</span>
          <span aria-hidden="true">|</span>
          <span>{t.scrollHint}</span>
          <span aria-hidden="true">|</span>
          <span>{t.loopRange}: 5–8小節</span>
        </div>
      </div>
    </ProtoShell>
  );
}

import { useCallback, useEffect, useMemo, useState } from "react";
import { Button } from "@fluentui/react-components";
import { Play24Regular } from "@fluentui/react-icons";
import { ja } from "../../strings/ja";
import {
  NOTES,
  buildIssues,
  type MockNote,
  type PitchView,
} from "../mockData";
import { useMockPlayer } from "../useMockPlayer";
import { useProtoKeys } from "../useProtoKeys";
import { ProtoScore } from "../ProtoScore";
import {
  ProtoProperties,
  ProtoShell,
  ReviewBanner,
  type ProtoCommand,
  type ProtoShellState,
} from "../ProtoChrome";

type ShellScreen = "empty" | "audioReady" | "transcribing" | "scoreReady";

const STAGES = [
  "preparingAudio",
  "transcribing",
  "cleaning",
  "analyzingRhythm",
  "quantizing",
  "buildingScore",
  "rendering",
] as const;

/**
 * P1 — app shell state. Walks the §27 screen machine with mock data:
 * EMPTY → AUDIO_READY → TRANSCRIBING → SCORE_READY. Validates that the
 * five shell regions (command bar / waveform / score / properties /
 * transport) hold up in every state.
 */
const PARAM_TO_SCREEN: Record<string, ShellScreen> = {
  empty: "empty",
  audio: "audioReady",
  transcribing: "transcribing",
  score: "scoreReady",
};

const SCREEN_TO_PARAM: Record<ShellScreen, string> = {
  empty: "empty",
  audioReady: "audio",
  transcribing: "transcribing",
  scoreReady: "score",
};

export function ShellPage({ initial }: { initial?: string }) {
  const [screen, setScreen] = useState<ShellScreen>(
    () => PARAM_TO_SCREEN[initial ?? ""] ?? "empty",
  );
  const [pitch, setPitch] = useState<PitchView>("concert");
  const [stage, setStage] = useState(0);
  const [selectedId, setSelectedId] = useState<string | null>(null);
  const [status, setStatus] = useState<string>(ja.status.ready);
  const [propsOpen, setPropsOpen] = useState(false);
  const player = useMockPlayer();

  const issues = useMemo(() => buildIssues(), []);
  const notes = useMemo<MockNote[]>(() => NOTES.map((n) => ({ ...n })), []);

  // Deterministic stage progression while TRANSCRIBING (mock timer).
  useEffect(() => {
    if (screen !== "transcribing") return;
    if (stage >= STAGES.length) {
      setScreen("scoreReady");
      setStatus(ja.prototype.transcribing.completed);
      return;
    }
    const id = window.setTimeout(() => setStage((s) => s + 1), 1100);
    return () => window.clearTimeout(id);
  }, [screen, stage]);

  const onCommand = useCallback((id: ProtoCommand) => {
    switch (id) {
      case "open":
        window.location.hash = "#/prototype/shell/audio";
        break;
      case "transcribe":
        window.location.hash = "#/prototype/shell/transcribing";
        break;
      case "review":
        window.location.hash = "#/prototype/review";
        break;
      case "export":
        window.location.hash = "#/prototype/export";
        break;
      case "settings":
        setStatus("設定画面はこのプロトタイプでは省略しています");
        break;
    }
  }, []);

  useProtoKeys(
    useMemo(
      () => [
        { combo: "Ctrl+o", run: () => onCommand("open") },
        { combo: "Ctrl+1", run: () => setPitch("concert") },
        { combo: "Ctrl+2", run: () => setPitch("hornF") },
        { combo: "Space", run: player.togglePlay, enabled: () => screen !== "empty" },
        { combo: "Escape", run: () => setSelectedId(null) },
      ],
      [onCommand, player.togglePlay, screen],
    ),
  );

  const state: ProtoShellState = {
    hasAudio: screen !== "empty",
    hasScore: screen === "scoreReady",
    reviewCount: screen === "scoreReady" ? issues.length : 0,
    transcribing: screen === "transcribing",
  };

  const selected = notes.find((n) => n.id === selectedId) ?? null;

  const devBar = (
    <div className="hs-proto-dev" role="group" aria-label={ja.prototype.dev.controlsLabel}>
      <span className="hs-proto-dev__label">{ja.prototype.dev.controlsLabel}</span>
      <span>{ja.prototype.dev.stateLabel}:</span>
      {(
        [
          ["empty", ja.prototype.shell.stateEmpty],
          ["audioReady", ja.prototype.shell.stateAudioReady],
          ["transcribing", ja.prototype.shell.stateTranscribing],
          ["scoreReady", ja.prototype.shell.stateScoreReady],
        ] as const
      ).map(([key, label]) => (
        <Button
          key={key}
          size="small"
          appearance={screen === key ? "primary" : "secondary"}
          onClick={() => {
            // hash change remounts the page → deterministic state
            window.location.hash = `#/prototype/shell/${SCREEN_TO_PARAM[key]}`;
          }}
        >
          {label}
        </Button>
      ))}
    </div>
  );

  return (
    <>
      {devBar}
      <ProtoShell
        documentTitle={screen === "empty" ? undefined : ja.prototype.shell.docTitle}
        state={state}
        pitch={pitch}
        onPitch={setPitch}
        onCommand={onCommand}
        player={player}
        transportEnabled={screen !== "empty"}
        status={status}
        properties={
          screen === "scoreReady" ? (
            <ProtoProperties
              note={selected}
              pitch={pitch}
              open={propsOpen}
              onClose={() => setPropsOpen(false)}
              onReopen={() => setPropsOpen(true)}
            />
          ) : undefined
        }
        banner={
          screen === "scoreReady" ? (
            <ReviewBanner count={issues.length} onOpen={() => onCommand("review")} />
          ) : undefined
        }
      >
        {screen === "empty" && (
          <main className="hs-score" role="region" aria-label={ja.score.regionLabel} tabIndex={0}>
            <div className="hs-empty">
              <p className="hs-empty__title">{ja.emptyState.title}</p>
              <p className="hs-empty__or">{ja.emptyState.or}</p>
              <Button
                appearance="primary"
                size="large"
                icon={<Play24Regular />}
                onClick={() => onCommand("open")}
              >
                {ja.emptyState.open}
              </Button>
              <p className="hs-empty__formats">{ja.emptyState.formats}</p>
              <p className="hs-empty__privacy">{ja.emptyState.privacy}</p>
            </div>
          </main>
        )}

        {screen === "audioReady" && (
          <main className="hs-score" role="region" aria-label={ja.score.regionLabel} tabIndex={0}>
            <div className="hs-empty">
              <p className="hs-empty__title">{ja.prototype.scoreEmpty.body}</p>
              <Button
                appearance="primary"
                size="large"
                icon={<Play24Regular />}
                onClick={() => onCommand("transcribe")}
              >
                {ja.prototype.scoreEmpty.cta}
              </Button>
            </div>
          </main>
        )}

        {screen === "transcribing" && (
          <main className="hs-score" role="region" aria-label={ja.score.regionLabel}>
            <div className="hs-proto-stages" aria-live="polite">
              <h2 className="hs-proto-stages__title">
                {ja.prototype.transcribing.running}
              </h2>
              <ul className="hs-proto-stages__list">
                {STAGES.map((key, i) => {
                  const label = ja.prototype.transcribing.stages[key];
                  const st = i < stage ? "done" : i === stage ? "active" : "pending";
                  return (
                    <li key={key} className="hs-proto-stages__item" data-state={st}>
                      <span className="hs-proto-stages__icon" aria-hidden="true">
                        {st === "done" ? "✓" : st === "active" ? "●" : "○"}
                      </span>
                      <span>{st === "done" ? label.done : st === "active" ? label.active : label.pending}</span>
                    </li>
                  );
                })}
              </ul>
              <p className="hs-proto-stages__note">{ja.prototype.shell.transcribeNote}</p>
              <Button onClick={() => setScreen("audioReady")}>
                {ja.prototype.transcribing.cancel}
              </Button>
            </div>
          </main>
        )}

        {screen === "scoreReady" && (
          <ProtoScore
            notes={notes}
            pitch={pitch}
            selectedId={selectedId}
            onSelect={(id) => {
              setSelectedId(id);
              setPropsOpen(true);
            }}
            positionSec={player.playing ? player.positionSec : null}
            issues={issues}
            onBackgroundClick={() => setSelectedId(null)}
          />
        )}
      </ProtoShell>
    </>
  );
}

/**
 * UI-009 prototype styles (issue #31). Scoped to src/prototype only.
