/* --------------------------- density frame --------------------------- */
.hs-proto-frame {
  width: 1366px;
  height: 768px;
  border: 2px solid var(--hs-border-strong);
  border-radius: var(--hs-radius-panel);
  overflow: hidden;
  position: relative;
  margin: var(--hs-space-sm) var(--hs-space-ms);
  flex: 0 0 auto;
}
.hs-proto-frame .hs-shell {
  height: 100%;
}
.hs-proto-doc {
  margin: var(--hs-space-sm) var(--hs-space-ms) var(--hs-space-md);
  padding: var(--hs-space-md);
  border: 1px dashed var(--hs-border-strong);
  border-radius: var(--hs-radius-panel);
  max-width: 960px;
  font-size: var(--hs-font-size-compact);
  color: var(--hs-text-secondary);
}
.hs-proto-doc h2 {
  margin: 0 0 var(--hs-space-xs);
  font-size: var(--hs-font-size-subtitle);
  color: var(--hs-text-primary);
}
.hs-proto-doc ol,
.hs-proto-doc ul {
  margin: var(--hs-space-xs) 0 0;
  padding-left: var(--hs-space-lg);
}
.hs-proto-doc li {
  margin-bottom: var(--hs-space-xs);
}
.hs-proto-scrollable {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
}

/* misc */
.hs-proto-kbd {
  font-family: inherit;
  font-size: inherit;
}

import { useCallback, useEffect, useRef, useState } from "react";
import { DURATION_SEC, LOOP_RANGE } from "./mockData";

export type FollowMode = "on" | "paused" | "off";

export interface MockPlayer {
  playing: boolean;
  positionSec: number;
  rate: number;
  loop: boolean;
  follow: FollowMode;
  play(): void;
  pause(): void;
  togglePlay(): void;
  stop(): void;
  seekTo(sec: number): void;
  seekBy(deltaSec: number): void;
  cycleRate(): void;
  toggleLoop(): void;
  /** Manual navigation while playing suspends follow (GUI_UX_SPEC §11). */
  suspendFollow(): void;
  resumeFollow(): void;
  setFollowOn(on: boolean): void;
}

const RATES = [0.75, 1, 1.25];
const TICK_MS = 100;

/**
 * Deterministic mock transport. Fixed tick, fixed rate steps, fixed loop
 * range — no audio backend. Follow state machine mirrors GUI_UX_SPEC §11:
 * ON → (manual scroll) → paused → [追従を再開] → ON.
 */
export function useMockPlayer(): MockPlayer {
  const [playing, setPlaying] = useState(false);
  const [positionSec, setPositionSec] = useState(0);
  const [rate, setRate] = useState(1);
  const [loop, setLoop] = useState(false);
  const [follow, setFollow] = useState<FollowMode>("on");
  const posRef = useRef(positionSec);
  posRef.current = positionSec;

  useEffect(() => {
    if (!playing) return;
    const id = window.setInterval(() => {
      setPositionSec((pos) => {
        let next = pos + (TICK_MS / 1000) * rate;
        if (loop && next >= LOOP_RANGE.endSec) next = LOOP_RANGE.startSec;
        if (next >= DURATION_SEC) {
          window.clearInterval(id);
          setPlaying(false);
          return DURATION_SEC;
        }
        return next;
      });
    }, TICK_MS);
    return () => window.clearInterval(id);
  }, [playing, rate, loop]);

  const clamp = useCallback(
    (sec: number) => Math.min(DURATION_SEC, Math.max(0, sec)),
    [],
  );

  const play = useCallback(() => {
    setPositionSec((pos) => (pos >= DURATION_SEC ? 0 : pos));
    setPlaying(true);
  }, []);
  const pause = useCallback(() => setPlaying(false), []);
  const togglePlay = useCallback(
    () => (playing ? pause() : play()),
    [playing, pause, play],
  );
  const stop = useCallback(() => {
    setPlaying(false);
    setPositionSec(0);
  }, []);
  const seekTo = useCallback((sec: number) => setPositionSec(clamp(sec)), [clamp]);
  const seekBy = useCallback(
    (delta: number) => setPositionSec((pos) => clamp(pos + delta)),
    [clamp],
  );
  const cycleRate = useCallback(
    () => setRate((r) => RATES[(RATES.indexOf(r) + 1) % RATES.length]),
    [],
  );
  const toggleLoop = useCallback(() => setLoop((v) => !v), []);
  const suspendFollow = useCallback(
    () => setFollow((f) => (f === "on" ? "paused" : f)),
    [],
  );
  const resumeFollow = useCallback(() => setFollow("on"), []);
  const setFollowOn = useCallback(
    (on: boolean) => setFollow(on ? "on" : "off"),
    [],
  );

  return {
    playing,
    positionSec,
    rate,
    loop,
    follow,
    play,
    pause,
    togglePlay,
    stop,
    seekTo,
    seekBy,
    cycleRate,
    toggleLoop,
    suspendFollow,
    resumeFollow,
    setFollowOn,
  };
}

import { useEffect } from "react";

/**
 * UI-009 prototype key map — the single place prototype pages bind keys,
 * mirroring the spirit of the §23 command registry (no scattered ad-hoc
 * handlers). Keys are matched against a normalized combo string such as
 * "Space", "Ctrl+1", "Alt+ArrowUp", "j", "Escape".
 *
 * Text-entry targets are skipped so keys never fight Japanese IME input.
 */

export interface KeyBinding {
  combo: string;
  run(): void;
  /** When set, the binding only fires while `enabled()` is true. */
  enabled?(): boolean;
}

function isTextEntry(target: EventTarget | null): boolean {
  if (!(target instanceof HTMLElement)) return false;
  return (
    target.tagName === "INPUT" ||
    target.tagName === "TEXTAREA" ||
    target.tagName === "SELECT" ||
    target.isContentEditable
  );
}

function comboOf(e: KeyboardEvent): string {
  const parts: string[] = [];
  if (e.ctrlKey) parts.push("Ctrl");
  if (e.altKey) parts.push("Alt");
  if (e.shiftKey) parts.push("Shift");
  const key = e.key === " " ? "Space" : e.key;
  parts.push(key.length === 1 ? key.toLowerCase() : key);
  return parts.join("+");
}

export function useProtoKeys(bindings: KeyBinding[]): void {
  useEffect(() => {
    const onKeyDown = (e: KeyboardEvent) => {
      if (isTextEntry(e.target)) return;
      const combo = comboOf(e);
      for (const b of bindings) {
        if (b.combo !== combo) continue;
        if (b.enabled && !b.enabled()) return;
        e.preventDefault();
        b.run();
        return;
      }
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, [bindings]);
}
